// Author: MiYu. Exercise source terrain and animated water on shared native GPU views; all validation captures default to tmp.
use mengine_assets::{AssetByteCache,WarcraftArchives,WarcraftMapSession,WarcraftMapLimits,WarcraftMapCancelToken,WarcraftTerrainLimits,WarcraftTerrainMaterial};
use mengine_editor_host::{MountedWarcraftTerrain,WarcraftTerrainRenderLimits};
use mengine_rhi::{Renderer,RenderFrame,RenderObject,RenderTarget,FrameCamera,FrameLighting,ClearColor,look_at,orthographic};
use glam::Vec3;
use std::{path::PathBuf,sync::Arc};
use winit::dpi::PhysicalSize;

fn draw(renderer:&mut Renderer,objects:&[RenderObject],camera:FrameCamera,target:&mengine_rhi::OffscreenRenderTarget)->anyhow::Result<Vec<u8>> {let mut lighting=FrameLighting::default(); lighting.environment.tone_mapping=false; lighting.environment.background_enabled=false; renderer.submit_frame_to(&RenderFrame {clear:ClearColor {r:0.03,g:0.02,b:0.04,a:1.},camera,objects,lighting:&lighting,ui:None,scene_views:&[]},RenderTarget::Offscreen(target))?; Ok(renderer.read_offscreen_rgba8(target)?)}
fn changed(a:&[u8],b:&[u8])->usize {a.chunks_exact(4).zip(b.chunks_exact(4)).filter(|(a,b)|a!=b).count()}
fn material_allocations(renderer:&Renderer)->Option<usize> {renderer.gpu_allocator_report().1.map(|r|r.allocations.iter().filter(|(n,_)|n.contains("material_texture")).count())}
fn main()->anyhow::Result<()> {
    let mut args=std::env::args_os().skip(1); let game=PathBuf::from(args.next().ok_or_else(||anyhow::anyhow!("Provide game directory and map path"))?); let map=PathBuf::from(args.next().ok_or_else(||anyhow::anyhow!("Provide map path"))?); let output=args.next().map(PathBuf::from).unwrap_or_else(||PathBuf::from("tmp/docs-artifacts/warcraft-archives/terrain-gpu")); anyhow::ensure!(args.next().is_none(),"Unexpected argument");
    let cache=Arc::new(AssetByteCache::default()); let archives=WarcraftArchives::open(&game,0,cache.clone(),16*1024*1024)?; let session=WarcraftMapSession::open(&archives,&map,WarcraftMapLimits::default(),&WarcraftMapCancelToken::default())?; let mounted=MountedWarcraftTerrain::load(&session,WarcraftTerrainLimits::default(),&WarcraftMapCancelToken::default())?;
    let water=mounted.terrain().water.as_ref().ok_or_else(||anyhow::anyhow!("Choose a source map with visible animated water"))?; anyhow::ensure!(water.settings.frame_count>1 && water.settings.frame_rate>0.,"Map water must animate"); let deep=water.tiles.iter().max_by(|a,b|{let width=session.terrain().size()[0]; let at=|p:&[u32;2]|((water.heights[(p[1]*width+p[0]) as usize]-mounted.terrain().layout.surface_heights[(p[1]*width+p[0]) as usize]).min(1.)*1000.) as i32; at(a).cmp(&at(b))}).unwrap();
    let origin=session.terrain().origin().map(|n|n/128.); let focus=Vec3::new(origin[0]+deep[0] as f32+0.5,water.heights[(deep[1]*session.terrain().size()[0]+deep[0]) as usize],-origin[1]-deep[1] as f32-0.5); let eye=focus+Vec3::new(0.,16.,14.); let camera=FrameCamera {view:look_at(eye,focus,Vec3::Y),proj:orthographic(10.,4./3.,0.1,100.),position:eye};
    let tiles=session.terrain().tile_size(); let cache_before=cache.stats(); drop(session); let cache_after=cache.stats(); anyhow::ensure!(cache_after.resident_bytes<cache_before.resident_bytes,"Map archive cache was retained after its data session closed");
    let size=PhysicalSize::new(800,600); let mut first=Renderer::new_shared_headless(size)?; let mut second=Renderer::new_shared_headless(size)?; let first_target=first.create_offscreen_target(size); let second_target=second.create_offscreen_target(size); let blank=draw(&mut first,&[],camera,&first_target)?;
    anyhow::ensure!(mounted.bind(&mut first,WarcraftTerrainRenderLimits {max_draws:1,..Default::default()}).is_err(),"Render budget must reject before uploading"); anyhow::ensure!(first.material_texture_stats().color==0 && first.material_texture_stats().data==0,"Rejected plan mutated textures");
    let mut view=mounted.bind(&mut first,WarcraftTerrainRenderLimits::default())?; let initial=draw(&mut first,view.objects(),camera,&first_target)?; let culling=first.spatial_culling_stats(); anyhow::ensure!(culling.camera_visible>0 && culling.camera_visible<culling.total,"Near view must cull source terrain chunks"); let visible=changed(&blank,&initial); anyhow::ensure!(visible>1000,"Source terrain is not visible"); anyhow::ensure!(first.surface_shader_diagnostics().is_empty(),"Source shaders were rejected");
    for (chunk,object) in mounted.terrain().chunks.iter().zip(view.objects()) {if matches!(chunk.material,WarcraftTerrainMaterial::Cliff(_)) {anyhow::ensure!(object.material.base_color==[1.;4],"Source cliff albedo must be white before sampling");}}
    let without_water=view.objects().iter().zip(&mounted.terrain().chunks).filter(|(_,c)|c.material!=WarcraftTerrainMaterial::Water).map(|(o,_)|o.clone()).collect::<Vec<_>>(); let dry=draw(&mut first,&without_water,camera,&first_target)?; let water_pixels=changed(&dry,&initial); anyhow::ensure!(water_pixels>100,"Water did not contribute visible pixels");
    let elapsed=(1000./water.settings.frame_rate as f64).ceil() as u64; anyhow::ensure!(view.set_elapsed_ms(elapsed),"Source water frame did not advance"); let animated=draw(&mut first,view.objects(),camera,&first_target)?; let animated_pixels=changed(&initial,&animated); anyhow::ensure!(animated_pixels>10,"Source water frames did not change GPU pixels"); view.set_elapsed_ms(0);
    let center=Vec3::new(origin[0]+tiles[0] as f32*0.5,1.,-origin[1]-tiles[1] as f32*0.5); let overview_eye=center+Vec3::new(0.,160.,120.); let overview_camera=FrameCamera {view:look_at(overview_eye,center,Vec3::Y),proj:orthographic((tiles[1] as f32).max(tiles[0] as f32/(4./3.))*0.6,4./3.,0.1,1000.),position:overview_eye}; let overview=draw(&mut first,view.objects(),overview_camera,&first_target)?;
    let before_shared=material_allocations(&first); let mut other=mounted.bind(&mut second,WarcraftTerrainRenderLimits::default())?; let after_shared=material_allocations(&second); let other_pixels=draw(&mut second,other.objects(),camera,&second_target)?; anyhow::ensure!(other_pixels==initial,"Shared native view differs"); anyhow::ensure!(other.upload_stats().vertex_buffers_reused==other.upload_stats().meshes,"Second view must share immutable vertex buffers"); if let (Some(a),Some(b))=(before_shared,after_shared) {anyhow::ensure!(a==b,"Second view duplicated material GPU textures");}
    anyhow::ensure!(view.release(&mut second).is_err(),"Wrong renderer released a view"); let old=view.objects().to_vec(); view.release(&mut first)?; anyhow::ensure!(draw(&mut first,&old,camera,&first_target)?==blank,"Released meshes still draw"); anyhow::ensure!(draw(&mut second,other.objects(),camera,&second_target)?==initial,"Release damaged another view"); let old_other=other.objects().to_vec(); other.release(&mut second)?; anyhow::ensure!(draw(&mut second,&old_other,camera,&second_target)?==blank,"Second released view still draws"); anyhow::ensure!(first.material_texture_stats().color==0 && first.material_texture_stats().data==0 && second.material_texture_stats().color==0 && second.material_texture_stats().data==0,"Released terrain still owns texture keys");
    let report=serde_json::json!({"scope":"Native source terrain and water GPU consumer; not full game or original Warcraft visual/FPS acceptance","map":map,"chunks":mounted.terrain().chunks.len(),"waterTiles":water.tiles.len(),"culling":{"total":culling.total,"cameraVisible":culling.camera_visible,"submitted":culling.submitted},"visiblePixels":visible,"waterPixels":water_pixels,"animatedPixels":animated_pixels,"secondaryUpload":other.upload_stats(),"materialGpuAllocationsBeforeSecond":before_shared,"materialGpuAllocationsAfterSecond":after_shared,"sessionClosedBeforeGpu":true,"mapCacheBytesReleased":cache_before.resident_bytes-cache_after.resident_bytes,"wrongRendererRejected":true,"bothViewsReleased":true,"otherViewPreserved":true,"output":output}); std::fs::create_dir_all(&output)?; for (name,pixels) in [("overview.png",&overview),("terrain.png",&initial),("water-next-frame.png",&animated),("without-water.png",&dry)] {image::save_buffer(output.join(name),pixels,size.width,size.height,image::ColorType::Rgba8)?;} std::fs::write(output.join("receipt.json"),serde_json::to_vec_pretty(&report)?)?; println!("{report}"); Ok(())
}
